-- ============================================
-- LUMA — Thème 4 : 3e scénario COURT x4 — Retrouver une valise perdue
-- ============================================


update scenarios set content = '{"characters": {"agent": "l''agent bagages"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You wait at the baggage carousel. Everyone''s luggage has come out except yours.)", "text_fr": "(Vous attendez au tapis à bagages. Tous les bagages sont sortis sauf le vôtre.)", "choices": [{"text": "(Wait a bit longer in case it''s just delayed.)", "text_fr": "(Attends encore un peu au cas où c''est juste en retard.)", "next": "n2"}, {"text": "(Head straight to the baggage service desk.)", "text_fr": "(Va directement au comptoir de service bagages.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(Ten more minutes pass, still nothing.)", "text_fr": "(Dix minutes de plus passent, toujours rien.)", "choices": [{"text": "Okay, time to report this.", "text_fr": "Bon, il est temps de signaler ça.", "next": "n2b"}]}, "n2b": {"speaker": "agent", "text": "Hi, how can I help you?", "text_fr": "Bonjour, comment puis-je vous aider ?", "choices": [{"text": "My suitcase didn''t arrive on the belt, I''d like to report it missing.", "text_fr": "Ma valise n''est pas arrivée sur le tapis, j''aimerais la signaler manquante.", "next": "n3"}]}, "n3": {"speaker": "agent", "text": "I''m sorry to hear that. Can I see your baggage claim tag and boarding pass?", "text_fr": "Je suis désolé d''entendre ça. Je peux voir votre étiquette de bagage et votre carte d''embarquement ?", "choices": [{"text": "Here you go.", "text_fr": "Voici.", "next": "n4"}, {"text": "Here they are — I hope it wasn''t left behind at the connection.", "text_fr": "Les voici — j''espère qu''elle n''a pas été oubliée à la correspondance.", "next": "n4"}]}, "n4": {"speaker": "agent", "text": "Let me check the system... it looks like it may have missed your connecting flight.", "text_fr": "Laissez-moi vérifier le système... on dirait qu''elle a peut-être raté votre vol de correspondance.", "choices": [{"text": "Okay, when can I expect it to arrive?", "text_fr": "D''accord, quand puis-je m''attendre à ce qu''elle arrive ?", "next": "n5"}, {"text": "That makes sense, the connection was quite tight.", "text_fr": "Ça se comprend, la correspondance était assez serrée.", "next": "n5"}]}, "n5": {"speaker": "agent", "text": "It should arrive on tomorrow''s flight. We can deliver it to your hotel.", "text_fr": "Elle devrait arriver sur le vol de demain. On peut la livrer à votre hôtel.", "choices": [{"text": "That would be great, here''s my hotel address.", "text_fr": "Ce serait super, voici l''adresse de mon hôtel.", "next": "n6"}, {"text": "Could I pick it up here myself instead?", "text_fr": "Je pourrais venir la récupérer ici moi-même plutôt ?", "next": "n6b"}]}, "n6": {"speaker": "agent", "text": "Perfect, I''ll note that down. You''ll also receive a reference number for tracking.", "text_fr": "Parfait, je note ça. Vous recevrez aussi un numéro de référence pour le suivi.", "choices": [{"text": "Thank you so much for your help.", "text_fr": "Merci beaucoup pour votre aide.", "next": "n7"}]}, "n6b": {"speaker": "agent", "text": "Of course, just come back tomorrow afternoon with your reference number.", "text_fr": "Bien sûr, revenez juste demain après-midi avec votre numéro de référence.", "choices": [{"text": "Perfect, thank you for explaining everything.", "text_fr": "Parfait, merci d''avoir tout expliqué.", "next": "n7"}]}, "n7": {"speaker": "agent", "text": "Here''s your reference number. We''re really sorry for the inconvenience.", "text_fr": "Voici votre numéro de référence. On est vraiment désolés pour ce désagrément.", "choices": [{"text": "No worries, thank you for handling it so quickly.", "text_fr": "Pas de souci, merci de l''avoir géré si rapidement.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "agent", "text": "You''re welcome, we''ll be in touch as soon as it arrives.", "text_fr": "Je vous en prie, on vous recontacte dès qu''elle arrive.", "end": true, "ending_label": "Valise perdue signalée efficacement 🧳✅"}}}'::jsonb, is_playable = true
where title = 'Retrouver une valise perdue'
  and theme_id = (select id from scenario_themes where position = 4 and language_id = (select id from languages where code = 'en'));
